```javascript
/**
 * Build a consolidated "Final" sheet: one row per respondent key.
 *
 * Source sheet "Clean" columns (row 1 = headers):
 *   A Timestamp | B Name | C Email | D JoinedBefore_norm |
 *   E Phone_norm | F Park_canon | G email_key | H time_parsed
 *
 * Grouping key:
 *   - If email_key is present: "e:" + email_key
 *   - Else if name present:    "n:" + lower(trim(name)) + "|" + floor(time_parsed / BUCKET_SECONDS)
 *   - Else: row is skipped (and reported in the log)
 *
 * Row selection within a group:
 *   1. Highest time_parsed wins.
 *   2. On ties, the row with the most non-blank fields across B,C,D,E,F wins.
 *   3. Remaining ties: first occurrence wins (stable).
 *
 * Field fill:
 *   For each output field, use the chosen row's value if non-blank; otherwise
 *   fall back to the most recent non-blank value for that field within the group.
 *
 * Conflicts:
 *   For each field, if the group has >1 distinct non-blank value, the field
 *   name is added to the CONFLICTS column (semicolon-separated).
 *
 * Idempotent: clears "Final" each run and rewrites headers + rows.
 */

const SOURCE_SHEET = 'Clean';
const TARGET_SHEET = 'Final';
const BUCKET_SECONDS = 600; // 10-minute window for no-email grouping

// Column indices in Clean (0-based)
const COL = {
  timestamp: 0,
  name: 1,
  email: 2,
  joined: 3,
  phone: 4,
  park: 5,
  emailKey: 6,
  timeParsed: 7,
};

// Fields that participate in "most non-blank" tiebreak, fallback, and conflict detection.
const FIELDS = [
  { key: 'name',   col: COL.name,   label: 'Name' },
  { key: 'email',  col: COL.email,  label: 'Email' },
  { key: 'joined', col: COL.joined, label: 'JoinedBefore' },
  { key: 'phone',  col: COL.phone,  label: 'Phone' },
  { key: 'park',   col: COL.park,   label: 'Park' },
];

function buildFinal() {
  const ss = SpreadsheetApp.getActive();
  const src = ss.getSheetByName(SOURCE_SHEET);
  if (!src) throw new Error(`Sheet "${SOURCE_SHEET}" not found.`);

  const lastRow = src.getLastRow();
  if (lastRow < 2) {
    writeFinal(ss, []);
    Logger.log('No data rows in Clean.');
    return;
  }

  const data = src.getRange(2, 1, lastRow - 1, 8).getValues();

  // Group rows by key
  const groups = new Map(); // key -> array of row objects
  let skipped = 0;

  data.forEach((row, i) => {
    const key = makeKey(row);
    if (!key) { skipped++; return; }

    const enriched = {
      rowIndex: i + 2,                 // 1-based row in Clean (for logs)
      time: toNumber(row[COL.timeParsed]),
      raw: row,
      nonBlankCount: FIELDS.reduce(
        (n, f) => n + (isBlank(row[f.col]) ? 0 : 1), 0
      ),
    };

    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(enriched);
  });

  // Build output rows
  const output = [];
  for (const [key, rows] of groups) {
    rows.sort((a, b) => {
      if (b.time !== a.time) return b.time - a.time;       // latest first
      if (b.nonBlankCount !== a.nonBlankCount) {
        return b.nonBlankCount - a.nonBlankCount;          // more complete first
      }
      return a.rowIndex - b.rowIndex;                      // stable
    });

    const chosen = rows[0];
    const latestTime = chosen.time;

    const outRow = {
      Key: key,
      Timestamp: latestTime ? new Date(latestTime * 1000) : '',
    };

    const conflicts = [];

    for (const f of FIELDS) {
      // Start with chosen row's value
      let value = chosen.raw[f.col];

      // Fallback: most recent non-blank in the group
      if (isBlank(value)) {
        for (let j = 1; j < rows.length; j++) {
          if (!isBlank(rows[j].raw[f.col])) {
            value = rows[j].raw[f.col];
            break;
          }
        }
      }
      outRow[f.label] = isBlank(value) ? '' : value;

      // Conflict check: distinct non-blank values across the group
      const distinct = new Set();
      for (const r of rows) {
        const v = r.raw[f.col];
        if (!isBlank(v)) distinct.add(normalizeForCompare(v));
      }
      if (distinct.size > 1) conflicts.push(f.label);
    }

    outRow.CONFLICTS = conflicts.join('; ');
    output.push(outRow);
  }

  // Sort output by timestamp desc for readability
  output.sort((a, b) => {
    const at = a.Timestamp instanceof Date ? a.Timestamp.getTime() : 0;
    const bt = b.Timestamp instanceof Date ? b.Timestamp.getTime() : 0;
    return bt - at;
  });

  writeFinal(ss, output);
  Logger.log(
    `Wrote ${output.length} rows to "${TARGET_SHEET}". Skipped ${skipped} source rows with no key.`
  );
}

// ---------- helpers ----------

function makeKey(row) {
  const emailKey = String(row[COL.emailKey] || '').trim().toLowerCase();
  if (emailKey) return 'e:' + emailKey;

  const name = String(row[COL.name] || '').trim().toLowerCase().replace(/\s+/g, ' ');
  const t = toNumber(row[COL.timeParsed]);
  if (name && t) {
    return 'n:' + name + '|' + Math.floor(t / BUCKET_SECONDS);
  }
  return '';
}

function isBlank(v) {
  if (v === null || v === undefined) return true;
  if (typeof v === 'string') return v.trim() === '';
  return false;
}

function toNumber(v) {
  if (v instanceof Date) return Math.floor(v.getTime() / 1000);
  const n = Number(v);
  return isFinite(n) ? n : 0;
}

function normalizeForCompare(v) {
  if (v instanceof Date) return 'd:' + v.getTime();
  return String(v).trim().toLowerCase();
}

function writeFinal(ss, rows) {
  let sheet = ss.getSheetByName(TARGET_SHEET);
  if (!sheet) sheet = ss.insertSheet(TARGET_SHEET);
  sheet.clear();

  const headers = ['Key', 'Timestamp', 'Name', 'Email', 'JoinedBefore', 'Phone', 'Park', 'CONFLICTS'];
  sheet.getRange(1, 1, 1, headers.length).setValues([headers]).setFontWeight('bold');
  sheet.setFrozenRows(1);

  if (rows.length === 0) return;

  const values = rows.map(r => headers.map(h => r[h] !== undefined ? r[h] : ''));
  sheet.getRange(2, 1, values.length, headers.length).setValues(values);

  // Format timestamp column
  sheet.getRange(2, 2, values.length, 1).setNumberFormat('yyyy-mm-dd hh:mm');
  // Format phone as plain text so leading zeros survive
  sheet.getRange(2, 6, values.length, 1).setNumberFormat('@');

  sheet.autoResizeColumns(1, headers.length);
}
```

**A few notes on the behavior**

- **Idempotent:** `sheet.clear()` wipes contents and formatting each run, then rewrites. Safe to run after every batch of new survey responses.
- **Tiebreakers in order:** latest `time_parsed` → most non-blank fields in B–F → first occurrence. Comment-documented in the sort so future-you can change it.
- **Conflict detection** uses a case-insensitive, trimmed comparison (`normalizeForCompare`). So `"West Side"` and `"west side"` won't falsely flag, but `"West Side"` vs `"North Park"` will.
- **Skipped rows:** anything with no email_key AND no name+time combination is skipped and reported via `Logger.log`. Open **View > Logs** (or Executions) after a run to see the count. If you want those rows surfaced on the Final sheet instead, say the word.
- **BUCKET_SECONDS = 600** matches the 10-minute window from the formulas. Change the constant at the top if you want wider/narrower grouping for no-email rows.
- **Phone column** is set to plain-text format so a value like `0551234` won't lose its leading zero on write.

**To run on a schedule:** in the Script Editor, click the clock icon (Triggers) → Add Trigger → function `buildFinal`, time-driven, e.g. hourly. Or add a custom menu with `onOpen` if you'd rather click a button — let me know and I'll add it.

