    .addItem('Build Final', 'buildFinal')
    .addItem('Open Clean Row', 'openCleanRow')
    .addToUi();
}

// ---------- open row prompt ----------

function openCleanRow() {
  const ui = SpreadsheetApp.getUi();
  const ss = SpreadsheetApp.getActive();
  const sheet = ss.getSheetByName(SOURCE_SHEET);
  if (!sheet) {
    ui.alert(`Sheet "${SOURCE_SHEET}" not found.`);
    return;
  }

