    ui.alert(`"${raw}" is not a valid row number.`);
    return;
  }
  const lastRow = sheet.getLastRow();
  if (row > lastRow) {
    ui.alert(`Row ${row} is beyond the last row (${lastRow}) in "${SOURCE_SHEET}".`);
    return;
  }

  ss.setActiveSheet(sheet);
