// ---------- main ----------

function buildFinal() {
  const ss = SpreadsheetApp.getActive();
  const src = ss.getSheetByName(SOURCE_SHEET);
  if (!src) throw new Error(`Sheet "${SOURCE_SHEET}" not found.`);

  const cleanGid = src.getSheetId();
  const ssUrl = ss.getUrl();

  const lastRow = src.getLastRow();
  if (lastRow < 2) {
    writeFinal(ss, [], ssUrl, cleanGid);
    Logger.log('No data rows in Clean.');
    return;
  }

  const data = src.getRange(2, 1, lastRow - 1, 8).getValues();

  const groups = new Map();
  let skipped = 0;

  data.forEach((row, i) => {
    const key = makeKey(row);
    if (!key) { skipped++; return; }

    const enriched = {
      rowIndex: i + 2,
      time: toNumber(row[COL.timeParsed]),
      raw: row,
      nonBlankCount: FIELDS.reduce(
        (n, f) => n + (isBlank(row[f.col]) ? 0 : 1), 0
      ),
    };

    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(enriched);
  });

  const output = [];
  for (const [key, rows] of groups) {
    rows.sort((a, b) => {
      if (b.time !== a.time) return b.time - a.time;
      if (b.nonBlankCount !== a.nonBlankCount) {
        return b.nonBlankCount - a.nonBlankCount;
      }
      return a.rowIndex - b.rowIndex;
    });

    const chosen = rows[0];
    const latestTime = chosen.time;
    const rowNumbers = rows.map(r => r.rowIndex);

    const outRow = {
      Key: key,
      Timestamp: latestTime ? new Date(latestTime * 1000) : '',
      SOURCE_ROWS: rowNumbers,
    };

    const conflicts = [];

    for (const f of FIELDS) {
      let value = chosen.raw[f.col];
      if (isBlank(value)) {
        for (let j = 1; j < rows.length; j++) {
          if (!isBlank(rows[j].raw[f.col])) {
            value = rows[j].raw[f.col];
            break;
          }
        }
      }
      outRow[f.label] = isBlank(value) ? '' : value;

      const seen = new Map();
      for (const r of rows) {
        const v = r.raw[f.col];
        if (isBlank(v)) continue;
        const norm = normalizeForCompare(v);
        if (!seen.has(norm)) seen.set(norm, displayValue(v));
      }

      if (seen.size > 1) {
        conflicts.push(f.label);
        outRow[f.label + '_values'] = Array.from(seen.values()).join(' | ');
      } else {
        outRow[f.label + '_values'] = '';
      }
    }

    outRow.CONFLICTS = conflicts.join('; ');
    output.push(outRow);
  }

  output.sort((a, b) => {
    const at = a.Timestamp instanceof Date ? a.Timestamp.getTime() : 0;
    const bt = b.Timestamp instanceof Date ? b.Timestamp.getTime() : 0;
    return bt - at;
  });

  writeFinal(ss, output, ssUrl, cleanGid);
  Logger.log(
    `Wrote ${output.length} rows to "${TARGET_SHEET}". Skipped ${skipped} source rows with no key.`
  );
}

